import type { BankQuestion } from "@/lib/bank";

/** Operating Systems (CS Fundamentals): 127 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cs-operating-systems-1", "question": "In the standard five-state process model, which transition can NEVER happen directly?", "options": ["Waiting → Running", "Running → Waiting", "Ready → Running", "Waiting → Ready"], "answer": 0, "explanation": "A process whose I/O or event completes moves from Waiting to Ready and must then be picked by the scheduler; it cannot jump straight to Running. The other three transitions are all normal.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-operating-systems-2", "question": "The data structure in which the OS keeps a process's program counter, register contents, state and open-file list is called the:", "options": ["Interrupt vector table", "Process Control Block (PCB)", "Page table", "Inode"], "answer": 1, "explanation": "The PCB (task control block) holds everything needed to resume a process after a context switch. An inode describes a file, not a process.", "difficulty": "easy", "source": "Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-3","question":"Short jobs stuck waiting behind one long CPU-bound job is called the convoy effect. It is characteristic of which scheduling algorithm?","options":["Round Robin","Shortest Remaining Time First","First Come First Served","Multilevel feedback queue"],"answer":2,"explanation":"FCFS is non-preemptive and ignores burst length, so a long job at the head of the queue holds up every short job behind it.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-4","question":"A system spends most of its time swapping pages in and out and does very little useful work. This condition is called:","options":["Deadlock","Belady's anomaly","Starvation","Thrashing"],"answer":3,"explanation":"Thrashing happens when processes do not have enough frames for their working sets, so page faults dominate and CPU utilisation collapses.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-5","question":"Which page-replacement algorithm can show Belady's anomaly (more frames giving more page faults)?","options":["FIFO","LRU","LFU implemented as a stack algorithm","Optimal (OPT)"],"answer":0,"explanation":"FIFO is not a stack algorithm, so the set of pages held with n frames is not always a subset of those held with n + 1 frames; that is what allows the anomaly. OPT and LRU are stack algorithms and never show it.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-6", "question": "The disk-scheduling algorithm in which the head sweeps to one end of the disk servicing requests and then reverses direction, like a lift, is:", "options": ["FCFS", "SCAN", "C-SCAN", "SSTF"], "answer": 1, "explanation": "SCAN is the elevator algorithm: it goes all the way to the end in the current direction, then reverses. C-SCAN instead jumps back to the start without servicing on the return.", "difficulty": "easy", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-7","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (times in ms). Under FCFS scheduling, what is the average waiting time?","options":["8.75 ms","4.00 ms","4.75 ms","5.25 ms"],"answer":2,"explanation":"Completion: P1 = 7, P2 = 11, P3 = 12, P4 = 16. Waiting = completion − arrival − burst = 0, 5, 7, 7, so the average is 19/4 = 4.75 ms. 8.75 ms is the average turnaround time, not waiting time.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-8","question":"Which of the following is NOT one of the four necessary (Coffman) conditions for deadlock?","options":["Mutual exclusion","Circular wait","Hold and wait","Preemption of resources"],"answer":3,"explanation":"The four conditions are mutual exclusion, hold and wait, NO preemption, and circular wait. Allowing preemption actually breaks a deadlock condition.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-9","question":"How many times is \"hi\" printed? (Assume every fork() succeeds.)\n```c\nint main() {\n    for (int i = 0; i < 3; i++)\n        fork();\n    printf(\"hi\\n\");\n    return 0;\n}\n```","options":["8","7","6","3"],"answer":0,"explanation":"Each fork doubles the number of processes, so after 3 forks there are 2³ = 8 processes and each prints once. 7 is the number of child processes created, not the number of printers.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-10","question":"A system has 32-bit logical addresses, a page size of 4 KB and 4-byte page-table entries. What is the size of a single-level page table for one process?","options":["4 KB","4 MB","1 MB","16 MB"],"answer":1,"explanation":"Pages = 2³² / 2¹² = 2²⁰ entries; 2²⁰ × 4 bytes = 4 MB. 1 MB is the entry count (in millions), forgetting the 4-byte entry size.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-11","question":"Four processes share a pool of identical resource instances, and each process needs at most 3 instances to finish. What is the minimum number of instances that guarantees deadlock can never occur?","options":["10","8","9","12"],"answer":2,"explanation":"Worst case: each process holds 3 − 1 = 2 instances and waits for one more, using 4 × 2 = 8. One extra instance lets some process finish, so 8 + 1 = 9 is the minimum. With 8, all four can be stuck.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-12", "question": "A counting semaphore S is initialised to 5. Then 7 wait (P) operations and 3 signal (V) operations are performed on it in some order. What is the final value of S (using the definition where S may go negative)?", "options": ["−2", "2", "15", "1"], "answer": 3, "explanation": "Each P subtracts 1 and each V adds 1: 5 − 7 + 3 = 1. The order affects which processes block on the way, not the final value.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-13","question":"A process of size 13,000 bytes is loaded with paging, page size 4,096 bytes. How much internal fragmentation is there in its last page?","options":["3,384 bytes","712 bytes","0 bytes, because paging has no internal fragmentation","1,096 bytes"],"answer":0,"explanation":"It needs ⌈13000/4096⌉ = 4 pages = 16,384 bytes, so 16,384 − 13,000 = 3,384 bytes are wasted in the last page. Paging removes external fragmentation, not internal.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-14","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using non-preemptive SJF (ties broken by arrival), what is the average turnaround time?","options":["7.00 ms","8.00 ms","4.00 ms","8.75 ms"],"answer":1,"explanation":"P1 runs 0–7 (only process at t = 0). At 7 all have arrived; shortest is P3 (7–8), then P2 (8–12), then P4 (12–16). Turnaround = 7, 10, 4, 11 → 32/4 = 8 ms. 4 ms is average waiting; 7 ms is what preemptive SRTF gives.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-15", "question": "A child process has terminated, but its parent has not yet called wait() to read its exit status. The child is now a:", "options": ["Daemon process", "Suspended process", "Zombie process", "Orphan process"], "answer": 2, "explanation": "A zombie keeps its PID and an entry in the process table until the parent reaps it with wait(). An orphan is the opposite case: the parent died first and init/systemd adopts the child.", "difficulty": "easy", "source": "Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-16", "question": "In a many-to-one thread model (many user-level threads mapped to one kernel thread), what happens when one thread makes a blocking system call?", "options": ["Only that thread blocks; the others keep running", "The call is converted to a non-blocking call by the CPU", "The kernel creates a new kernel thread automatically", "The entire process blocks"], "answer": 3, "explanation": "The kernel sees only one schedulable entity, so a blocking call blocks all threads of that process. One-to-one models (Linux, Windows) avoid this but cost a kernel thread per user thread.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-17","question":"Which disadvantage applies to linked file allocation but NOT to indexed allocation?","options":["Direct (random) access to the i-th block requires following i pointers","Files cannot grow after creation","Space is needed to store an index block","External fragmentation"],"answer":0,"explanation":"With linked allocation, reaching block i means walking the chain from the first block, so random access is slow. Neither linked nor indexed allocation suffers external fragmentation, and the index-block overhead belongs to indexed allocation.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-18","question":"A disk has cylinders 0–199 and the head is at cylinder 72. The request queue, in arrival order, is 110, 25, 160, 47, 130, 8, 95, 185. What is the total head movement under FCFS?","options":["641 cylinders","753 cylinders","290 cylinders","818 cylinders"],"answer":1,"explanation":"|72−110| + |110−25| + |25−160| + |160−47| + |47−130| + |130−8| + |8−95| + |95−185| = 38 + 85 + 135 + 113 + 83 + 122 + 87 + 90 = 753.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-19", "question": "A disk spins at 7,200 RPM. What is its average rotational latency?", "options": ["8.33 ms", "0.14 ms", "4.17 ms", "2.08 ms"], "answer": 2, "explanation": "One rotation = 60/7200 s = 8.33 ms; on average the sector is half a rotation away, so latency = 4.17 ms. 8.33 ms is the full rotation time.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-20","question":"Which statement about a page fault is correct?","options":["It is handled entirely by the MMU without involving the OS","It means the process tried to access an illegal address and is always terminated","It occurs when the TLB misses","It occurs when the referenced page is valid but not currently in main memory"],"answer":3,"explanation":"A page fault traps to the OS when the valid page is not resident; the OS loads it and restarts the instruction. A TLB miss is resolved by walking the page table and need not be a page fault; an invalid address is a different trap (segmentation fault).","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-21","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using preemptive SJF (Shortest Remaining Time First), what is the average waiting time?","options":["3.00 ms","4.00 ms","2.50 ms","7.00 ms"],"answer":0,"explanation":"Gantt: P1 0–2, P2 2–4, P3 4–5, P2 5–7, P4 7–11, P1 11–16. Waiting = 9, 1, 0, 2 → 12/4 = 3 ms. 4 ms is the non-preemptive SJF answer; 7 ms is the average turnaround.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-22","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Using Round Robin with time quantum 2 ms, what is the average turnaround time? A process arriving at the same instant a quantum expires joins the ready queue before the preempted process.","options":["8.75 ms","9.00 ms","11.00 ms","5.00 ms"],"answer":1,"explanation":"Gantt: P1 0–2, P2 2–4, P1 4–6, P3 6–7, P2 7–9, P4 9–11, P1 11–13, P4 13–15, P1 15–16. Completion 16, 9, 7, 15 → turnaround 16, 7, 3, 10 = 36/4 = 9 ms. 5 ms is the average waiting time.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-23","question":"Cylinders 0–199, head at 72. Requests: 110, 25, 160, 47, 130, 8, 95, 185. What is the total head movement under SSTF?","options":["264 cylinders","318 cylinders","290 cylinders","329 cylinders"],"answer":2,"explanation":"From 72 the nearest is 95 (23 away; 47 is 25 away), then 110, 130, 160, 185, then back to 47, 25, 8. Movement = (185 − 72) + (185 − 8) = 113 + 177 = 290.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-24","question":"Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4. With 3 frames, initially empty, how many page faults does FIFO produce?","options":["9","12","10","11"],"answer":3,"explanation":"Faults on 3, 1, 4 (cold), then 2 (evict 3), 1 is a hit, 5 (evict 1), 3 (evict 4), 4 (evict 2), 1 (evict 5), 2 (evict 3), 5 (evict 4), 4 (evict 1). Only references 3 (4th) and 1 (6th) hit, so 13 − 2 = 11 faults.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-25","question":"A paging system with a single-level page table has a TLB lookup time of 10 ns, a memory access time of 80 ns, and a TLB hit ratio of 85%. The TLB is searched before the page table. What is the effective memory access time?","options":["102 ns","93.5 ns","110 ns","90 ns"],"answer":0,"explanation":"Hit: 10 + 80 = 90 ns. Miss: 10 + 80 (page table) + 80 (data) = 170 ns. EMAT = 0.85 × 90 + 0.15 × 170 = 76.5 + 25.5 = 102 ns. Forgetting the TLB time on a miss gives a wrong lower value.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-26","question":"Memory access time is 100 ns and servicing a page fault takes 10 ms. If 1 access in 1,000 causes a page fault, the effective access time is about:","options":["10 ms","10.1 μs","1.1 μs","100.1 ns"],"answer":1,"explanation":"EAT = 0.999 × 100 ns + 0.001 × 10,000,000 ns = 99.9 + 10,000 ≈ 10,100 ns ≈ 10.1 μs, a 100-fold slowdown. The common slip is to forget converting 10 ms to 10⁷ ns.","difficulty":"moderate","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-27","question":"Five processes P0–P4 and three resource types A, B, C. Allocation: P0 (1,0,1), P1 (2,1,1), P2 (0,1,2), P3 (1,1,0), P4 (0,0,2). Max: P0 (4,2,3), P1 (3,2,2), P2 (2,3,4), P3 (3,1,2), P4 (1,2,3). Available: (1,1,1). Using the Banker's algorithm, which of these is a safe sequence?","options":["P4, P1, P3, P0, P2","P3, P1, P4, P0, P2","P1, P3, P4, P0, P2","P0, P1, P3, P4, P2"],"answer":2,"explanation":"Need = Max − Allocation: P0 (3,2,2), P1 (1,1,1), P2 (2,2,2), P3 (2,0,2), P4 (1,2,1). Only P1 fits in (1,1,1); then Work = (3,2,2) → P3 → (4,3,2) → P4 → (4,3,4) → P0 → (5,3,5) → P2. Starting with P3 or P4 fails because their need exceeds (1,1,1).","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-28","question":"Two processes must run statements S1 (in P1) and S2 (in P2) such that S2 never executes before S1. Using one semaphore `sync`, which is correct?","options":["sync = 1; P1: wait(sync); S1; signal(sync);   P2: S2;","sync = 1; P1: S1; signal(sync);   P2: wait(sync); S2;","sync = 0; P1: wait(sync); S1;   P2: S2; signal(sync);","sync = 0; P1: S1; signal(sync);   P2: wait(sync); S2;"],"answer":3,"explanation":"With sync = 0, P2's wait blocks until P1 has done S1 and signalled. Initialising sync to 1 lets P2 pass wait immediately, so S2 could run first.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-29","question":"A system has 32-bit virtual addresses, 4 KB pages and 4-byte page-table entries, and every page table must fit exactly in one page. How should the virtual address be split for a multilevel page table?","options":["Two levels: 10 + 10 + 12","Single level: 20-bit page number + 12-bit offset","Two levels: 8 + 12 + 12","Three levels: 7 + 7 + 6 + 12"],"answer":0,"explanation":"Offset = 12 bits (4 KB). One page holds 4096/4 = 1024 = 2¹⁰ entries, so each level resolves 10 bits; the 20-bit page number needs 20/10 = 2 levels: 10 + 10 + 12.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-30","question":"A Unix-style inode has 12 direct pointers, 1 single-indirect and 1 double-indirect pointer. The block size is 1 KB and a block pointer is 4 bytes. What is the maximum file size?","options":["12 KB + 1 MB + 1 GB","12 KB + 256 KB + 64 MB","268 KB","12 KB + 256 KB + 256 MB"],"answer":1,"explanation":"One block holds 1024/4 = 256 pointers. Direct: 12 × 1 KB; single-indirect: 256 × 1 KB = 256 KB; double-indirect: 256 × 256 × 1 KB = 64 MB. 268 KB ignores the double-indirect pointer.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-31","question":"Memory holes, in order, are 150 KB, 450 KB, 250 KB, 350 KB and 500 KB. Requests arrive in order: 240 KB, 410 KB, 130 KB, 380 KB. Which placement strategy satisfies ALL four requests?","options":["First fit only","Worst fit only","Best fit only","First fit and worst fit"],"answer":2,"explanation":"First fit: 240→450, 410→500, 130→150, then 380 finds no hole ≥ 380 (largest is 350). Worst fit: 240→500, 410→450, 130→350, then 380 fails. Best fit: 240→250, 410→450, 130→150, 380→500, so all fit.","difficulty":"hard","source":"Wipro · Cognizant pattern"},
  {"id":"cs-operating-systems-32","question":"What does this program print? (Assume fork() succeeds; the order of the two lines may vary.)\n```c\nint x = 5;\nint main() {\n    if (fork() == 0) x++;\n    else x--;\n    printf(\"%d \", x);\n    return 0;\n}\n```","options":["5 5","6 6","6 5","6 4"],"answer":3,"explanation":"After fork the child and parent have separate copies of x (copy-on-write). The child increments its copy to 6, the parent decrements its own to 4. Changes in one are not seen by the other, even though x is global.","difficulty":"hard","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-33","question":"A resource-allocation graph contains a cycle. Which conclusion is correct?","options":["If every resource type in the cycle has exactly one instance, there is a deadlock; otherwise there may or may not be one","The system is deadlocked only if every process is in the cycle","There is never a deadlock unless the graph also has a self-loop","The system is always deadlocked"],"answer":0,"explanation":"With single-instance resources a cycle is necessary and sufficient for deadlock. With multiple instances a cycle is only necessary: another instance may be freed by a process outside the cycle.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id":"cs-operating-systems-34","question":"Reference string (times 1 to 14): 3, 5, 3, 1, 4, 4, 2, 1, 1, 6, 6, 6, 2, 5. With working-set window Δ = 4 references, what is the working set at time 12 (i.e. just after the 12th reference)?","options":["{6}","{1, 6}","{1, 2, 6, 4}","{2, 1, 6}"],"answer":1,"explanation":"The window covers references 9–12: 1, 6, 6, 6. Distinct pages = {1, 6}, so the working-set size is 2. Including reference 13 (page 2) uses the wrong window.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-35", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Priorities: A = 3, B = 1, C = 4, D = 2 (lower number = higher priority). Under PREEMPTIVE priority scheduling, what is the average waiting time?", "options": ["6.00", "5.25", "5.50", "4.75"], "answer": 2, "explanation": "Gantt: A 0–1, B 1–4 (preempts A), D 4–10, A 10–14, C 14–22. Waiting = 9, 0, 12, 1 → 22/4 = 5.5. Note D does not preempt B because B has higher priority. Non-preemptive priority gives 5.25.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-36","question":"Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under C-LOOK, counting the jump back as head movement, what is the total head movement?","options":["290 cylinders","318 cylinders","329 cylinders","373 cylinders"],"answer":2,"explanation":"Service 95, 110, 130, 160, 185 (113 cylinders), jump to 8 (177), then 25, 47 (39). Total = 113 + 177 + 39 = 329. 373 is C-SCAN (going to 199 and 0); 290 is LOOK.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-37","question":"In the first readers–writers problem (readers get priority: a reader never waits if the resource is already being read), which problem can occur?","options":["Two writers may write simultaneously","Readers can starve","A reader and a writer may access the data together","Writers can starve"],"answer":3,"explanation":"As long as readers keep arriving, readcount never drops to 0 and the writer's wait on the resource semaphore never succeeds. Mutual exclusion is still preserved; only fairness suffers.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-38","question":"When is a spinlock (busy-waiting lock) preferable to a blocking lock?","options":["On a multiprocessor when the lock is held for a very short time, shorter than two context switches","On a single-CPU system when the lock is held for a long time","When there are more threads than CPUs and the lock is heavily contended for long periods","Whenever the critical section performs disk I/O"],"answer":0,"explanation":"Spinning avoids the cost of sleeping and waking (two context switches). It is useful only if another CPU will release the lock soon; on a uniprocessor the spinning thread just wastes its quantum because the holder cannot run.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-39","question":"Modern fork() implementations use copy-on-write. Which statement is correct?","options":["Only the stack is copied; heap and data remain shared","Pages are shared read-only after fork, and a page is duplicated only when either process writes to it","The entire address space is copied immediately, but lazily mapped","Parent and child share all pages forever, so a write by one is seen by the other"],"answer":1,"explanation":"After fork, both page tables point to the same frames marked read-only. The first write causes a protection fault, and the kernel then copies just that page. Semantics stay as if the whole space were copied.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id": "cs-operating-systems-40", "question": "Segment table (base, limit): S0 (1400, 600), S1 (6300, 400), S2 (4300, 300), S3 (3200, 1100). What happens for logical addresses (2, 120) and (1, 450)?", "options": ["(2, 120) → 4180; (1, 450) → trap", "Both cause a trap", "(2, 120) → 4420; (1, 450) → 6750", "(2, 120) → 4420; (1, 450) → trap: offset exceeds limit"], "answer": 3, "explanation": "(2, 120): offset 120 < limit 300, physical = 4300 + 120 = 4420. (1, 450): offset 450 ≥ limit 400, so the hardware traps to the OS (addressing error). Adding base without checking the limit gives the tempting 6750.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-operating-systems-41","question":"Page size is 1 KB. The page table maps page 0 → frame 3, page 1 → frame 7, page 2 → frame 5, page 3 → frame 2. What physical address corresponds to logical address 2500?","options":["2500","5120","5572","7620"],"answer":2,"explanation":"Page = ⌊2500/1024⌋ = 2, offset = 2500 − 2048 = 452. Page 2 → frame 5, so physical = 5 × 1024 + 452 = 5572. 5120 forgets the offset.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-operating-systems-42","question":"Which statement about threads of the same process is FALSE?","options":["They share the code section and global data","They share open files","Each has its own program counter and register set","They share the same stack"],"answer":3,"explanation":"Each thread needs its own stack (local variables, return addresses) plus its own PC and registers. Code, data, heap and open files are shared.","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-operating-systems-43", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Round Robin, quantum 4. A context switch costs 1 time unit and happens whenever the CPU moves to a different process (none at t = 0, none when the same process continues). A process arriving at the same instant a quantum expires joins the ready queue before the preempted process. What is the average turnaround time?", "options": ["18.75", "20.00", "17.00", "15.25"], "answer": 0, "explanation": "A 0–4, cs, B 5–8 (done), cs, C 9–13, cs, D 14–18, cs, A 19–20 (done), cs, C 21–25 (done), cs, D 26–28 (done). Turnaround = A 20, B 7, C 23, D 25 → 75/4 = 18.75. Without overhead the schedule ends at 22 and gives 15.25.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-44","question":"Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms). Round Robin with quantum 3 ms. A process arriving at the same instant a quantum expires joins the ready queue before the preempted process. What is the completion time of P2, and what is the average response time (first run − arrival)?","options":["P2 completes at 9; average response 1.50 ms","P2 completes at 14; average response 2.75 ms","P2 completes at 13; average response 2.75 ms","P2 completes at 14; average response 3.00 ms"],"answer":1,"explanation":"Gantt: P1 0–3, P2 3–6, P1 6–9, P3 9–10, P4 10–13, P2 13–14, P1 14–15, P4 15–16. P3 and P4 arrive during P2's slice and join the queue behind P1, so P2's second turn comes only at 13. Response times 0, 1, 5, 5 → 11/4 = 2.75 ms.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-45", "question": "Processes: A (arrival 0, burst 5), B (arrival 1, burst 3), C (arrival 2, burst 8), D (arrival 3, burst 6). Priorities A = 3, B = 1, C = 4, D = 2 (lower number = higher priority). Compare preemptive and non-preemptive priority scheduling. Which statement is correct?", "options": ["Preemptive gives 4.75 and non-preemptive 5.25", "Preemptive gives the lower average waiting time, 5.25 vs 5.50", "Non-preemptive gives the lower average waiting time, 5.25 vs 5.50", "Both give 5.50"], "answer": 2, "explanation": "Non-preemptive: A 0–5, B 5–8, D 8–14, C 14–22 → waits 0, 4, 12, 5 = 5.25. Preemptive: A 0–1, B 1–4, D 4–10, A 10–14, C 14–22 → waits 9, 0, 12, 1 = 5.5. Preemption helps high-priority jobs but does not always lower the average.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-46","question":"Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4, 3 frames, initially empty. Which statement is correct?","options":["FIFO and LRU both give 11 faults","LRU gives 12 faults and OPT gives 9","FIFO gives 11 faults and LRU gives 12, so LRU is worse here","LRU gives fewer faults than FIFO, as it always does"],"answer":2,"explanation":"FIFO: 11 faults (hits on the 4th and 6th references). LRU: only the 4th reference (3) hits, so 12 faults. OPT gives 7. LRU is usually better than FIFO but not on every string, which is the trap.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-47", "question": "Reference string: 3, 1, 4, 3, 2, 1, 5, 3, 4, 1, 2, 5, 4. With 3 frames, initially empty, how many page faults does the Optimal (OPT) algorithm produce?", "options": ["6", "9", "8", "7"], "answer": 3, "explanation": "Faults: 3, 1, 4 (cold); 3 hit; 2 replaces 4 (used furthest away); 1 hit; 5 replaces 2 (next used at position 11, later than 3 and 1); 3 hit; 4 replaces 3 (not used again); 1 hit; 2 replaces 1; 5 hit; 4 hit. Total 7.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-48", "question": "Assertion (A): For FIFO page replacement, increasing the number of frames can increase the number of page faults.\nReason (R): FIFO is a stack algorithm, so the pages in memory with n frames are always a subset of those with n + 1 frames.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, R is false", "A is false, R is true"], "answer": 2, "explanation": "A is Belady's anomaly and is true. R is false: FIFO is NOT a stack algorithm; the inclusion property holds for LRU and OPT, which is exactly why they never show the anomaly.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-49","question":"Five processes P0–P4 and three resource types A, B, C. Allocation: P0 (1,0,1), P1 (2,1,1), P2 (0,1,2), P3 (1,1,0), P4 (0,0,2). Max: P0 (4,2,3), P1 (3,2,2), P2 (2,3,4), P3 (3,1,2), P4 (1,2,3). Available: (1,1,1). P4 now requests (0, 0, 1). What should the Banker's algorithm do?","options":["Make P4 wait, because the resulting state would be unsafe","Grant it, and the safe sequence becomes P4, P1, P3, P0, P2","Grant it, since the request ≤ Need and ≤ Available","Abort P4, because the request exceeds its maximum claim"],"answer":0,"explanation":"The request passes both checks (≤ Need (1,2,1), ≤ Available (1,1,1)). Pretending to grant it: Available = (1,1,0), P4's need = (1,2,0). Now P1 needs (1,1,1), but C = 0, and nobody else fits either, so the state is unsafe and P4 must wait. Passing the two checks is not enough.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-50","question":"A system has 6 identical tape drives. Each of n processes needs at most 2 drives. What is the maximum n for which the system is guaranteed to be deadlock-free?","options":["3","5","4","6"],"answer":1,"explanation":"Deadlock-free if n(2 − 1) + 1 ≤ 6, i.e. n ≤ 5. With 6 processes each could hold 1 drive and wait for a second with none left. Dividing 6 by 2 to get 3 is the common mistake.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-51", "question": "How many of the following statements about deadlock are correct?\n1. Requiring a process to request all its resources at once prevents hold-and-wait but can lower resource utilisation.\n2. Imposing a total order on resource types and requesting them only in increasing order prevents circular wait.\n3. An unsafe state always means the system is deadlocked.\n4. The Banker's algorithm needs each process to declare its maximum demand in advance.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is false: an unsafe state only means deadlock is possible; processes may release resources before requesting their maximum, so it may never happen.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-52","question":"Semaphores S = 1 and T = 0. Process X runs: wait(S); print('A'); signal(T);  Process Y runs: wait(T); print('B'); signal(S);  Each runs its code in an infinite loop. Which output prefix is possible?","options":["ABBA…","AABB…","ABAB…","BABA…"],"answer":2,"explanation":"Y cannot print until X signals T, and X cannot print again until Y signals S, so prints strictly alternate starting with A: ABAB… Any other pattern needs two consecutive prints by the same process, which the semaphores forbid.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-53", "question": "Two threads each run the loop `for (i = 0; i < 5; i++) count++;` on a shared int count = 0, with no synchronisation. count++ is compiled to load, add, store. What is the MINIMUM possible final value of count?", "options": ["5", "0", "1", "2"], "answer": 3, "explanation": "Interleaving: T1 loads 0; T2 runs 4 full iterations (count = 4); T1 stores 1; T2 loads 1; T1 runs its remaining 4 iterations; T2 stores 2. Final = 2. It cannot be lower: the last store comes from some thread's 5th iteration, whose load happens after that thread's own 4th store, so it reads at least 1 and writes at least 2.", "difficulty": "very-hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-54","question":"How many times is \"x\" printed? (fork() returns 0 in the child and a positive PID in the parent; assume it always succeeds.)\n```c\nint main() {\n    if (fork() && fork())\n        fork();\n    printf(\"x\\n\");\n    return 0;\n}\n```","options":["4","8","3","5"],"answer":0,"explanation":"&& short-circuits: the first child gets 0 and skips the second fork. The parent forks again; that second child gets 0, so the condition is false. Only the original parent enters the if and forks once more. Processes = parent + 3 children = 4.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-55","question":"How many times is \"x\" printed? (Assume every fork() succeeds.)\n```c\nint main() {\n    fork();\n    fork() || fork();\n    printf(\"x\\n\");\n    return 0;\n}\n```","options":["4","6","8","5"],"answer":1,"explanation":"After the first fork there are 2 processes. In each, the parent of `fork() || fork()` sees a non-zero value and skips the second fork; the child sees 0 and forks again. So each of the 2 processes becomes 3, giving 2 × 3 = 6.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-56","question":"How many lines are printed in total? (Assume every fork() succeeds.)\n```c\nint main() {\n    for (int i = 0; i < 3; i++) {\n        if (fork() == 0)\n            printf(\"%d\\n\", i);\n    }\n    return 0;\n}\n```","options":["12","8","7","3"],"answer":2,"explanation":"Only a newly created child prints, once, at the moment it is created, and then continues the loop. Forks: 1 at i = 0, 2 at i = 1, 4 at i = 2, so 7 lines (one 0, two 1s, four 2s). 8 would count the original process, which never prints.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-57","question":"A 64-bit machine uses 48-bit virtual addresses, 4 KB pages and 8-byte page-table entries. Every page table occupies exactly one page. How many levels of paging are needed?","options":["3","5","2","4"],"answer":3,"explanation":"Offset = 12 bits, leaving 36 bits of page number. One page holds 4096/8 = 512 = 2⁹ entries, so each level resolves 9 bits: 36/9 = 4 levels (as on x86-64). Three levels would cover only 27 of the 36 bits.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-58","question":"A system uses two-level paging and a TLB. TLB access = 10 ns, memory access = 100 ns, TLB hit ratio = 90%. The TLB is searched first, and on a miss both page-table levels are read from memory. What is the effective memory access time?","options":["130 ns","140 ns","210 ns","120 ns"],"answer":0,"explanation":"Hit: 10 + 100 = 110 ns. Miss: 10 + 100 + 100 (two table levels) + 100 (data) = 310 ns. EMAT = 0.9 × 110 + 0.1 × 310 = 99 + 31 = 130 ns. Counting only one table access on a miss gives 120 ns.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-59","question":"TLB access = 20 ns, memory access = 100 ns, single-level page table, TLB searched first. What is the minimum TLB hit ratio for the effective access time to be at most 125 ns?","options":["80%","95%","97.5%","90%"],"answer":1,"explanation":"EAT = h(120) + (1 − h)(220) = 220 − 100h ≤ 125, so h ≥ 0.95. Equivalently, the miss penalty is one extra 100 ns access and only 5 ns of it is allowed on average.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-60", "question": "Memory access takes 100 ns and a page fault takes 5 ms to service. For the effective access time to be at most 20% slower than a fault-free access, the page-fault rate must be at most about:", "options": ["1 in 2,500,000", "1 in 2,500", "1 in 250,000", "1 in 25,000"], "answer": 2, "explanation": "EAT = 100 + p(5,000,000 − 100) ≤ 120 ns, so p ≤ 20/4,999,900 ≈ 4 × 10⁻⁶, about 1 fault per 250,000 accesses. Forgetting that 5 ms = 5 × 10⁶ ns gives wrong options by factors of 1000.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-61","question":"A machine has 1 GB of physical memory, 4 KB pages, 64-bit virtual addresses and an inverted page table. How many entries does the inverted page table have, and on what does that number depend?","options":["2²⁰ entries, set by the page size alone","2⁵² entries, set by virtual address size","2¹⁸ entries per process","2¹⁸ entries, set by physical memory size"],"answer":3,"explanation":"An inverted table has one entry per physical frame, shared by all processes: 2³⁰/2¹² = 2¹⁸. Its size does not depend on the virtual address space, which is why it suits 64-bit systems.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-operating-systems-62", "question": "How many of the following statements are correct?\n1. Increasing the degree of multiprogramming always increases CPU utilisation.\n2. Thrashing can be reduced by lowering the degree of multiprogramming.\n3. If the sum of working-set sizes exceeds the number of available frames, thrashing is likely.\n4. Under a global replacement policy, one thrashing process can cause others to thrash.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "2, 3 and 4 are correct. 1 is false: past a point, extra processes push the system into thrashing and CPU utilisation falls sharply.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-63","question":"Cylinders 0–199, head at 72 currently moving towards cylinder 0. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under SCAN, what is the total head movement?","options":["257 cylinders","318 cylinders","241 cylinders","290 cylinders"],"answer":0,"explanation":"Down: 47, 25, 8 then on to cylinder 0 (72 cylinders), then up to 95, 110, 130, 160, 185 (185 cylinders). Total = 72 + 185 = 257. Turning at 8 instead of 0 is LOOK and gives 241; 318 is SCAN in the upward direction.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-64","question":"Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Under C-SCAN, counting the return sweep from 199 to 0 as head movement, what is the total head movement?","options":["318 cylinders","373 cylinders","329 cylinders","374 cylinders"],"answer":1,"explanation":"Up to 199 servicing 95…185: 127. Return 199 → 0: 199. Then 8, 25, 47: 47. Total = 127 + 199 + 47 = 373. C-LOOK (no trip to the ends) gives 329; SCAN gives 318.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id": "cs-operating-systems-65", "question": "Cylinders 0–199, head at 72 moving towards higher cylinders. Requests: 110, 25, 160, 47, 130, 8, 95, 185. Which two algorithms give the SAME total head movement for this queue?", "options": ["SCAN and LOOK", "SCAN and C-SCAN", "SSTF and LOOK", "SSTF and C-LOOK"], "answer": 2, "explanation": "SSTF goes 95, 110, 130, 160, 185 then 47, 25, 8, which is exactly LOOK's order here: both total 113 + 177 = 290. SCAN = 318 (goes on to 199), C-LOOK = 329, C-SCAN = 373.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-operating-systems-66", "question": "Processes: P1 (arrival 0, burst 7), P2 (arrival 2, burst 4), P3 (arrival 4, burst 1), P4 (arrival 5, burst 4) (ms), scheduled by SRTF. Not counting the initial dispatch at t = 0 or the switch away from the last process when it finishes, how many context switches occur?", "options": ["6", "3", "4", "5"], "answer": 3, "explanation": "Gantt: P1 0–2 | P2 2–4 | P3 4–5 | P2 5–7 | P4 7–11 | P1 11–16. Switches at 2, 4, 5, 7 and 11 = 5. P4 arriving at 5 does not preempt P2 (remaining 2 < 4), a common miscount.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-67","question":"A disk rotates at 7,200 RPM, has 400 sectors of 512 bytes per track, and an average seek time of 5 ms. What is the average time to read 4 KB stored in consecutive sectors of one track?","options":["9.33 ms","9.17 ms","13.50 ms","5.17 ms"],"answer":0,"explanation":"Rotation = 8.333 ms; average latency = 4.167 ms. 4 KB = 8 sectors, transfer = 8/400 × 8.333 = 0.167 ms. Total = 5 + 4.167 + 0.167 = 9.33 ms. Forgetting the transfer time gives 9.17; using a full rotation as latency gives 13.50.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id": "cs-operating-systems-68", "question": "Two processes use this code for mutual exclusion; `turn` is shared and starts at 0. Which property does it FAIL?\n```c\n// Process i (i = 0 or 1)\nwhile (true) {\n    while (turn != i) ;   // busy wait\n    /* critical section */\n    turn = 1 - i;\n    /* remainder section */\n}\n```", "options": ["It satisfies all three requirements", "Both mutual exclusion and bounded waiting", "Mutual exclusion", "Progress"], "answer": 3, "explanation": "Strict alternation guarantees mutual exclusion and bounded waiting, but if process 0 wants to enter twice in a row while process 1 stays in its remainder section, process 0 is blocked by a process not interested in entering. That violates progress. Peterson's algorithm fixes it with flag[].", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-69","question":"Producer–consumer with semaphores mutex = 1, empty = N, full = 0. The producer is written as:\n```c\nwait(mutex);\nwait(empty);\n/* add item */\nsignal(mutex);\nsignal(full);\n```\nThe consumer is correct (wait(full); wait(mutex); … signal(mutex); signal(empty);). What can go wrong?","options":["Nothing; the order of the two waits does not matter","Deadlock when the buffer is full: the producer holds mutex while blocked on empty, so the consumer can never enter","Two producers can add items at the same time","The consumer can remove from an empty buffer"],"answer":1,"explanation":"If the buffer is full, the producer acquires mutex and then blocks on empty. The consumer passes wait(full) but blocks on wait(mutex), so neither can proceed. The counting semaphore must be waited on before the mutex.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-70","question":"Match each scheduling algorithm with its property:\n(P) Round Robin  (Q) SRTF  (R) Multilevel feedback queue  (S) FCFS\n(1) Moves processes between queues based on observed CPU usage\n(2) Response time depends on the time quantum\n(3) Non-preemptive and prone to the convoy effect\n(4) Preemptive version of SJF; long jobs may starve","options":["P-1, Q-4, R-2, S-3","P-3, Q-4, R-1, S-2","P-2, Q-4, R-1, S-3","P-2, Q-1, R-4, S-3"],"answer":2,"explanation":"RR's responsiveness is set by the quantum; SRTF is preemptive SJF and can starve long jobs; MLFQ demotes CPU-heavy and promotes waiting processes; FCFS is non-preemptive with the convoy effect.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id": "cs-operating-systems-71", "question": "How many of the following statements are correct?\n1. On a context switch, the TLB must be flushed unless its entries carry an address-space identifier (ASID).\n2. A TLB miss always causes a page fault.\n3. Larger pages reduce page-table size but increase internal fragmentation.\n4. Pure demand paging loads every page of a process at start-up so that later references never fault.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only 1 and 3 are correct. 2 is false: on a TLB miss the page table is walked, and if the page is resident the TLB is simply refilled. 4 is false: demand paging loads a page only when it is first referenced, so a pure demand-paged process starts with page faults.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-operating-systems-72","question":"A 16 GB disk is formatted with 4 KB blocks and a File Allocation Table (FAT) that has one 4-byte entry per block. How large is the FAT, and why does it matter?","options":["16 MB; it must be read from disk for every block of every file","4 MB; it is stored inside each file's first block","64 MB; one entry per byte of the block","16 MB; it is usually cached in memory so following a file's block chain does not need a disk read per block"],"answer":3,"explanation":"Blocks = 16 GB / 4 KB = 4M = 2²²; 2²² × 4 B = 16 MB. FAT is linked allocation with the links pulled into one table, so caching it makes random access a walk through memory rather than through the disk.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-operating-systems-73", "question": "How many of the following statements about semaphores and mutexes are correct?\n1. A binary semaphore can be used to achieve mutual exclusion.\n2. A mutex can be released only by the thread that acquired it, whereas a semaphore can be signalled by any thread.\n3. A counting semaphore initialised to 3 lets at most 3 threads into the guarded section at once.\n4. wait() and signal() must themselves execute atomically.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four hold. Ownership (2) is the key difference that makes a mutex suitable for locking and a semaphore suitable for signalling between threads; atomicity (4) is what makes either work.", "difficulty": "hard", "source": "IBM · Deloitte pattern"},
  {"id":"cs-operating-systems-74","question":"Process L (low priority) holds a lock that high-priority process H needs. Medium-priority process M, which does not need the lock, becomes ready and preempts L. What is this situation called, and what fixes it?","options":["Priority inversion; fixed by priority inheritance (L temporarily runs at H's priority)","Deadlock; fixed by the Banker's algorithm","Convoy effect; fixed by Round Robin","Starvation; fixed by aging"],"answer":0,"explanation":"H is effectively blocked by M, a lower-priority process: priority inversion. With priority inheritance, L inherits H's priority while holding the lock, so M cannot preempt it; L releases the lock quickly and H runs.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-operating-systems-75","question":"Consider this loop:\n```c\nfor (int i = 0; i < 2; i++) {\n    fork();\n    printf(\"-\");\n}\n```\nstdout is redirected to a file (fully buffered) and no fflush is called. How many dashes appear in the file?","options":["4","8","3","6"],"answer":1,"explanation":"6 printf calls run in total, but the buffer is copied by fork. At i = 1, the 2 processes each hold \"-\" unflushed and fork, so all 4 final processes hold \"--\" and flush at exit: 4 × 2 = 8. With line-buffered output and a newline it would be 6.","difficulty":"very-hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-operating-systems-76","question":"Which CPU scheduling algorithm can make a long process wait indefinitely if short processes keep arriving?","options":["First-Come, First-Served (FCFS)","Round Robin","None — no scheduling algorithm can cause starvation","Shortest Job First (SJF)"],"answer":3,"explanation":"SJF always prefers the shortest job, so a long job can starve while shorter ones keep arriving. FCFS and Round Robin serve every process in turn, so they do not starve anyone.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-77","question":"Which part of the operating system selects which process in the ready queue gets the CPU next?","options":["Short-term (CPU) scheduler","Long-term (job) scheduler","Medium-term scheduler","Loader"],"answer":0,"explanation":"The short-term scheduler picks the next ready process; the dispatcher then performs the actual switch. The long-term scheduler controls admission into memory, and the medium-term scheduler handles swapping.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-78","question":"Processes (arrival, burst): P1 (0, 4), P2 (1, 3), P3 (2, 6), P4 (4, 2). What is the average turnaround time under FCFS?","options":["4.25","8","9","7.5"],"answer":1,"explanation":"Completion times: P1 4, P2 7, P3 13, P4 15. Turnaround = completion − arrival: 4, 6, 11, 11, average 32/4 = 8. 4.25 is the average waiting time; 9 forgets to subtract arrival times for P2.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-79","question":"Reference string: 1, 3, 0, 3, 5, 6, 3, 1, 0, 6, 5, 3. With 3 frames, initially empty, how many page faults does FIFO replacement cause?","options":["10","9","11","7"],"answer":2,"explanation":"FIFO hits only on the second reference (3); every later page has just been evicted when it returns: faults at 1, 3, 0, 5, 6, 3, 1, 0, 6, 5, 3 = 11. 7 is the Optimal count for the same string.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-80","question":"Pure paging (fixed-size pages and frames) can suffer from which kind of fragmentation?","options":["External fragmentation between frames","Both internal and external fragmentation equally","Neither kind","Internal fragmentation, in the last page of a process"],"answer":3,"explanation":"Any free frame can hold any page, so there is no external fragmentation, but a process rarely fills its last page exactly, wasting part of it. Variable-size segmentation is what suffers external fragmentation.","difficulty":"easy","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-81","question":"The Banker’s algorithm is used for which strategy of handling deadlocks?","options":["Deadlock avoidance","Deadlock prevention","Deadlock detection and recovery","Ignoring deadlocks (ostrich approach)"],"answer":0,"explanation":"The Banker’s algorithm grants a request only if the resulting state is safe, i.e. it avoids unsafe states using advance knowledge of maximum needs. Prevention instead breaks one of the four Coffman conditions by design.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-82","question":"If the time quantum of Round Robin scheduling is made larger than the longest CPU burst of every process, Round Robin behaves like:","options":["SJF","FCFS","Priority scheduling","Shortest Remaining Time First"],"answer":1,"explanation":"With such a huge quantum, every process finishes its burst before its quantum expires, so processes simply run to completion in arrival order — FCFS. A very small quantum instead causes heavy context-switch overhead.","difficulty":"easy","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-83","question":"Processes (arrival, burst): P1 (0, 6), P2 (2, 2), P3 (3, 4), P4 (5, 1). Round Robin with quantum 2 is used; a newly arrived process joins the ready queue before a process whose quantum just expired. What is the average waiting time?","options":["4","3","3.5","6.75"],"answer":2,"explanation":"Gantt: P1 0–2, P2 2–4, P1 4–6, P3 6–8, P4 8–9, P1 9–11, P3 11–13. Completions: P1 11, P2 4, P3 13, P4 9. Waiting = TAT − burst: 5, 0, 6, 3 → 14/4 = 3.5. 6.75 is the average turnaround time.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-84","question":"Processes (arrival, burst): P1 (0, 8), P2 (1, 4), P3 (2, 2), P4 (3, 5). What is the average waiting time under preemptive SJF (Shortest Remaining Time First)?","options":["5.75","4","9","4.25"],"answer":3,"explanation":"P1 0–1, P2 1–2 (4 < 7), P3 2–4 (2 < 3), P2 4–7, P4 7–12, P1 12–19. Waiting: P1 11, P2 2, P3 0, P4 4 → 17/4 = 4.25. 9 is the average turnaround time.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-85","question":"Reference string: 5, 2, 5, 8, 2, 3, 5, 9, 8, 2, 3, 5. With 3 frames, initially empty, how many page faults does LRU replacement cause?","options":["10","9","7","8"],"answer":0,"explanation":"Hits occur only at the 3rd reference (5) and 5th (2); after that each page returns just after being the least recently used: faults at 5, 2, 8, 3, 5, 9, 8, 2, 3, 5 = 10. Optimal would need 7.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-86","question":"Reference string: 1, 3, 0, 3, 5, 6, 3, 1, 0, 6, 5, 3. With 3 frames, initially empty, how many page faults does the Optimal (Belady’s MIN) algorithm cause?","options":["6","7","8","11"],"answer":1,"explanation":"1, 3, 0 fault (3). At 5 evict 0 (used farthest ahead) → 4. At 6 evict 5 → 5. 3 and 1 hit. At 0 evict 1 (never used again) → 6. 6 hits. At 5 evict 0 or 6 → 7. 3 hits. Total 7; FIFO gives 11.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-87","question":"A disk has cylinders 0–199 and the head is at cylinder 100. Pending requests: 45, 130, 12, 180, 90, 150, 60. What is the total head movement under SSTF?","options":["280","348","256","246"],"answer":2,"explanation":"From 100 the nearest is 90 (10), then 60 (30), 45 (15), 12 (33); now 130 is nearest (118), then 150 (20), 180 (30). Total 256. 280 is SCAN towards 0, which travels all the way to cylinder 0 before reversing.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-88","question":"Three processes share a single resource type with identical instances. Their maximum needs are 3, 4 and 5 instances. What is the minimum number of instances that guarantees deadlock can never occur?","options":["12","9","13","10"],"answer":3,"explanation":"Worst case: each process holds one less than its maximum, (3 − 1) + (4 − 1) + (5 − 1) = 9, and all are stuck. One more instance lets some process finish and release its holdings, so 9 + 1 = 10. 12 is the total maximum demand, which is more than needed.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-89","question":"Which of the following is NOT a requirement for a correct solution to the critical-section problem?","options":["Processes must enter the critical section in the order they arrive (FIFO)","Mutual exclusion","Progress","Bounded waiting"],"answer":0,"explanation":"The three classical requirements are mutual exclusion, progress (a free critical section cannot be postponed indefinitely), and bounded waiting (a limit on how often others can enter first). Strict FIFO order is stronger than required.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-90","question":"Under Highest Response Ratio Next (non-preemptive), the CPU becomes free at time 9. Ready processes (arrival, burst): P2 (2, 3), P3 (4, 6), P4 (6, 2). Which process runs next?","options":["P4","P2","P3","P2 and P4 tie"],"answer":1,"explanation":"Response ratio = (waiting + burst) / burst. P2: (7 + 3)/3 ≈ 3.33; P3: (5 + 6)/6 ≈ 1.83; P4: (3 + 2)/2 = 2.5. P2 has the highest ratio. Pure SJF would pick P4; HRRN boosts jobs that have waited long.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-91","question":"Reference string: 6, 1, 6, 2, 0, 1, 6, 4, 2, 1, 0, 4, 6. With 3 frames, initially empty, which set of page-fault counts is correct for FIFO, LRU and Optimal?","options":["FIFO 12, LRU 11, Optimal 8","FIFO 11, LRU 10, Optimal 8","FIFO 11, LRU 12, Optimal 8","FIFO 11, LRU 12, Optimal 7"],"answer":2,"explanation":"Simulating: FIFO faults 11, LRU 12, Optimal 8. LRU is usually better than FIFO, but not on every string — here LRU keeps evicting exactly the page needed next. Only Optimal is guaranteed to be the minimum.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-92","question":"Disk cylinders 0–199; the head is at cylinder 100 and moving towards cylinder 0. Requests: 45, 130, 12, 180, 90, 150, 60. What is the total head movement under SCAN (elevator), which goes to the end of the disk before reversing?","options":["256","268","378","280"],"answer":3,"explanation":"Moving down: 100 → 90 → 60 → 45 → 12 → 0 = 100 cylinders, then up: 0 → 180 = 180. Total 280. LOOK would turn at 12 instead of 0, giving 256. 378 would be C-SCAN-style jumping that is not SCAN.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-93","question":"Working-set window Δ = 4 references. Reference string (times 1 to 10): 1, 2, 1, 3, 4, 4, 3, 5, 1, 2. What is the working set at time 6 (covering references 3 to 6)?","options":["{1, 3, 4}","{1, 2, 3, 4}","{3, 4}","{4, 3, 5}"],"answer":0,"explanation":"References 3–6 are 1, 3, 4, 4, so the distinct pages are {1, 3, 4} (size 3). Including page 2 uses a window of 5; {4, 3, 5} looks at references 6–8 instead.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-94","question":"In a two-process mutual-exclusion attempt, each process sets its own flag to true and then waits while the other’s flag is true; there is no turn variable (as in Peterson’s algorithm). What can go wrong?","options":["Both may enter the critical section together","Both may set their flags at the same time and then wait for each other forever","One process can enter twice while the other waits forever, but no deadlock is possible","Nothing; flags alone are enough for two processes"],"answer":1,"explanation":"Mutual exclusion holds (a process enters only after seeing the other’s flag false), but if both set their flags before either checks, each waits for the other: deadlock, violating progress. Peterson adds “turn” so one of them always gives way.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-operating-systems-95","question":"A system runs 4 independent processes, each spending 80% of its time waiting for I/O. Assuming waits are independent, what is the approximate CPU utilisation?","options":["About 80%","About 20%","About 59%","About 41%"],"answer":2,"explanation":"The CPU is idle only when all four processes are waiting at once: 0.8⁴ ≈ 0.41. Utilisation = 1 − 0.8⁴ ≈ 0.59. 41% is the idle fraction; 80% wrongly adds 4 × 20%.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-operating-systems-96","question":"Processes (arrival, burst, priority — lower number is higher priority): P1 (0, 5, 3), P2 (1, 3, 1), P3 (2, 4, 4), P4 (4, 2, 2). Under preemptive priority scheduling, at what time does P1 complete?","options":["5","8","14","10"],"answer":3,"explanation":"P1 runs 0–1, then P2 (priority 1) preempts and runs 1–4. At 4, P4 (priority 2) beats P1 and runs 4–6. P1 resumes 6–10 with its remaining 4 units. P3 runs last, 10–14. 8 forgets P4’s preemption.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-operating-systems-97","question":"int A[256][256] is stored in row-major order, and a page holds 512 ints (two rows). The process has only ONE frame for A, initially empty. How many page faults does this loop cause?\n```c\nfor (j = 0; j < 256; j++)\n    for (i = 0; i < 256; i++)\n        A[i][j] = 0;\n```","options":["32768","128","65536","256"],"answer":0,"explanation":"The loop walks down a column. Rows i and i + 1 (for even i) share a page, so each column touches 128 pages, each faulting because the single frame was holding a different page: 128 × 256 = 32768. A row-wise loop would fault only 128 times; 65536 forgets that two rows share a page.","difficulty":"very-hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-operating-systems-98","question":"Processes (times in ms): A (arrival 0, burst 9), B (arrival 1, burst 4), C (arrival 3, burst 6), D (arrival 5, burst 2), E (arrival 8, burst 5). They are scheduled by SRTF (preemptive shortest remaining time first; ties go to the earlier arrival). What are the average waiting time and the average turnaround time?","options":["5.2 ms and 10.4 ms","4.6 ms and 9.8 ms","5.2 ms and 15.6 ms","6.8 ms and 12.0 ms"],"answer":0,"explanation":"Gantt chart: A 0-1, B 1-5 (B's 4 beats A's remaining 8), D 5-7, C 7-13 (at 7 C has 6 left against A's 8), E 13-18, A 18-26. At time 8, E arrives with 5 against C's remaining 5; the tie goes to C, the earlier arrival (breaking it the other way swaps C's and E's waits, 4 + 5 versus 9 + 0, and leaves the averages unchanged). Completion times A 26, B 5, C 13, D 7, E 18, so turnarounds 26, 4, 10, 2, 10 (average 10.4) and waits 17, 0, 4, 0, 5 (average 5.2). The usual slip is to let A run at time 7: C's 6 remaining beats A's 8.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-99","question":"Processes (times in ms): A (arrival 0, burst 9), B (arrival 1, burst 4), C (arrival 3, burst 6), D (arrival 5, burst 2), E (arrival 8, burst 5). Round Robin with time quantum 3 is used. A newly arrived process joins the tail of the ready queue before a process whose quantum expires at that same instant. When does E complete, and what is the average waiting time?","options":["E completes at 24; average waiting time 11.4 ms","E completes at 26; average waiting time 11.4 ms","E completes at 26; average waiting time 10.2 ms","E completes at 21; average waiting time 9.8 ms"],"answer":1,"explanation":"Queue trace: A 0-3 (B and C arrive; queue B, C, A). B 3-6 (D arrives at 5; queue C, A, D, B). C 6-9 (E arrives at 8; queue A, D, B, E, C). A 9-12, D 12-14 (done), B 14-15 (done), E 15-18, C 18-21 (done), A 21-24 (done), E 24-26 (done). Completion times A 24, B 15, C 21, D 14, E 26; waits 15, 10, 12, 7, 13, sum 57, average 11.4 ms. The placement rule matters at t = 3, where C's arrival and A's preemption coincide: putting A ahead of C reorders the whole chart.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-100","question":"Processes (arrival, burst, priority; a smaller number means higher priority): A (0, 9, 3), B (1, 4, 1), C (3, 6, 4), D (5, 2, 2), E (8, 5, 2). Preemptive priority scheduling is used. What is the average response time (first run minus arrival) and when does C finish?","options":["Average response time 0 ms; C finishes at 26","Average response time 3.4 ms; C finishes at 20","Average response time 3.4 ms; C finishes at 26","Average response time 4.4 ms; C finishes at 26"],"answer":2,"explanation":"A runs 0-1, B (priority 1) preempts and runs 1-5, then D (priority 2, arrived at 5) runs 5-7. A resumes 7-8, E (priority 2) arrives at 8 and preempts A, running 8-13. A finishes 13-20 and C, the lowest priority, runs 20-26. Response times: A 0, B 0, C 20 - 3 = 17, D 0, E 0; average 17/5 = 3.4 ms. Only C ever waits before its first run, and it waits long - the starvation risk of static priorities in miniature.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-101","question":"Processes (arrival, burst) in ms: P1 (0, 6), P2 (2, 5), P3 (4, 2), P4 (5, 8), P5 (7, 3). They are scheduled by non-preemptive Highest Response Ratio Next, where response ratio = (waiting time + burst) / burst. In what order do they run, and what is the average waiting time?","options":["P1, P3, P2, P5, P4; 6.2 ms","P1, P3, P5, P2, P4; 4.6 ms","P1, P2, P3, P5, P4; 5.8 ms","P1, P3, P2, P5, P4; 5 ms"],"answer":3,"explanation":"At 6: ratios P2 (4 + 5)/5 = 1.8, P3 (2 + 2)/2 = 2, P4 (1 + 8)/8 = 1.125, so P3 runs 6-8. At 8: P2 (6 + 5)/5 = 2.2, P4 (3 + 8)/8 = 1.375, P5 (1 + 3)/3 = 1.33, so P2 runs 8-13. At 13: P4 (8 + 8)/8 = 2, P5 (6 + 3)/3 = 3, so P5 runs 13-16 and P4 16-24. Waits 0, 6, 2, 11, 6: average 5 ms. Plain SJF would pick P5 over P2 at time 8 and give 4.6 ms; HRRN chooses P2 because it has already waited 6 ms, which is the aging HRRN is designed for.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-102","question":"A multilevel feedback queue has Q0 (Round Robin, quantum 2), Q1 (Round Robin, quantum 4) and Q2 (FCFS). New processes enter Q0. A process that uses its whole quantum moves down one level. A process running from a lower queue is preempted as soon as a process arrives in a higher queue; the preempted process goes to the tail of its own queue and gets a fresh quantum later. Processes (arrival, burst): A (0, 7), B (1, 5), C (3, 2), D (9, 6). What are the completion times of A, B, C and D?","options":["A 16, B 14, C 6, D 20","A 13, B 17, C 6, D 20","A 16, B 14, C 6, D 19","A 12, B 16, C 6, D 20"],"answer":0,"explanation":"A runs 0-2 in Q0 and drops to Q1. B runs 2-4 in Q0 and drops to Q1 (queue A, B). C runs 4-6 in Q0 and finishes. A runs from Q1 at 6, but D arrives in Q0 at 9, so A is preempted after 3 units and goes behind B. D runs 9-11 and drops to Q1 (queue B, A, D). B runs its last 3 units 11-14, A its last 2 units 14-16, D its last 4 units 16-20. Letting A finish its full Q1 quantum before D runs gives A 13 and pushes B to 17.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-103","question":"Three processes each run CPU burst, I/O burst, CPU burst (in ms): P1 arrives at 0 with 5, 4, 3; P2 arrives at 2 with 3, 6, 2; P3 arrives at 3 with 2, 2, 4. The CPU uses non-preemptive SJF on the length of the next CPU burst (ties go to whoever became ready first, then lower number). Every process has its own I/O device, so I/O never waits. When does each process finish?","options":["P1 13, P2 17, P3 19","P1 13, P2 19, P3 17","P1 15, P2 19, P3 17","P1 13, P2 18, P3 17"],"answer":1,"explanation":"P1 runs 0-5, then does I/O until 9. At 5, P3 (2) beats P2 (3): P3 runs 5-7 and does I/O until 9. P2 runs 7-10 and does I/O until 16. At 10, P1 (3 left) and P3 (4 left) are both ready since 9; SJF picks P1, 10-13, done. P3 runs 13-17, done. P2 becomes ready at 16 and runs 17-19, done. The CPU is never idle. Taking P2 first at time 5 because it arrived earlier is the FCFS habit that SJF overrides.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-104","question":"Reference string: 2, 7, 2, 4, 1, 7, 3, 2, 4, 5, 1, 2, 7, 3, 5, 2. With 4 frames, initially empty, how many page faults do FIFO, LRU and Optimal replacement cause, respectively?","options":["FIFO 8, LRU 10, Optimal 7","FIFO 12, LRU 8, Optimal 7","FIFO 8, LRU 12, Optimal 7","FIFO 8, LRU 12, Optimal 6"],"answer":2,"explanation":"Simulate each policy. FIFO: faults on 2, 7, 4, 1 (fill), 3 (evicts 2), 2 (evicts 7), 5 (evicts 4), 7 (evicts 1) - all other references hit, total 8. LRU keeps evicting exactly the page that comes back next on this string: the first 3 evicts 2, which is the very next reference; that 2 evicts 4, which is needed immediately after - 12 faults in all. Optimal faults 7 times: the 6 distinct pages each cost one compulsory miss, plus one re-load of 7. The trap is to assume LRU always beats FIFO; it is a stack algorithm, so it never shows Belady's anomaly, but it can lose to FIFO on a particular string.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-105","question":"Reference string: 2, 7, 2, 4, 1, 7, 3, 2, 4, 5, 1, 2, 7, 3, 5, 2. Three frames, initially empty, are managed by the clock (second-chance) algorithm: a hit sets the page's reference bit to 1; on a fault the hand skips frames whose bit is 1 (clearing the bit and advancing), replaces the first frame whose bit is 0, loads the new page with its bit set to 1, and advances one frame. Empty frames are filled in order. How many page faults occur?","options":["9","15","13","14"],"answer":3,"explanation":"Trace the hand. Loads 2, 7 (2 is hit and keeps bit 1), 4 fills the frames. Fault on 1: all bits are 1, so the hand clears them all and comes back to replace 2. 7 is a hit. On 3 the hand clears 7's bit and replaces 4; on 2 it replaces 7... continuing, only the references 2 (third), 7 (sixth) hit, giving 16 - 2 = 14 faults - the same as FIFO here, while LRU gives 15 and Optimal 9. Clock approximates LRU, but when every bit is set it degenerates into FIFO, which is what happens on this string.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-106","question":"Reference string: 2, 3, 4, 1, 2, 3, 1, 5, 2, 3, 4, 1, 5. How many page faults does FIFO give with 3 frames and with 4 frames, and LRU with 3 frames and with 4 frames (all frames initially empty)?","options":["FIFO 9 then 10; LRU 12 then 8","FIFO 10 then 9; LRU 12 then 8","FIFO 9 then 10; LRU 8 then 12","FIFO 9 then 9; LRU 12 then 10"],"answer":0,"explanation":"FIFO with 3 frames faults 9 times, and with 4 frames 10 times - Belady's anomaly, caused by FIFO's eviction order: with more frames, the page evicted just before it is needed again can differ. LRU is a stack algorithm (the set of pages held with n frames is always a subset of the set held with n + 1), so adding a frame can never add faults; here it drops from 12 to 8. Any option with LRU rising is impossible for that reason.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-107","question":"Reference string: 2, 7, 2, 4, 1, 7, 3, 2, 4, 5, 1, 2, 7, 3, 5, 2. Three frames, initially empty, use LFU replacement: the victim is the resident page with the smallest total reference count so far (counts include references made while the page was not resident), and ties go to the page that was loaded earliest. How many page faults occur?","options":["14","12","11","15"],"answer":1,"explanation":"Keep a running count per page. After 2, 7, 2, 4 the frames hold 2 (count 2), 7 and 4. On 1, the tie between 7 and 4 (count 1) is broken by load time, so 7 goes; then 7 itself faults and replaces 4 (count 1, oldest among the lowest). Continuing, page 2 gathers the highest count and is never evicted, which gives 2 fewer faults than FIFO's 14. Total 12. Resetting counts on eviction (a different LFU variant) changes the victims, which is why the rule is stated.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-108","question":"Five processes P0-P4 share four resource types A, B, C, D. Allocation: P0 (0,1,0,1), P1 (2,0,0,1), P2 (1,1,1,0), P3 (0,0,2,1), P4 (1,0,1,0). Max: P0 (3,2,2,2), P1 (2,1,1,3), P2 (2,2,1,1), P3 (1,2,3,2), P4 (3,1,2,1). Available: (1,1,1,1). How many distinct safe sequences exist?","options":["4","1","8","12"],"answer":2,"explanation":"Need = Max - Allocation: P0 (3,1,2,1), P1 (0,1,1,2), P2 (1,1,0,1), P3 (1,2,1,1), P4 (2,1,1,1). With (1,1,1,1) only P2 fits, so every safe sequence starts with P2, giving (2,2,2,1). Now P3 or P4 fits but P1 (needs 2 of D) does not; P0 needs 3 of A. After P2, P3 the pool is (2,2,4,2): P1 and P4 can run, and P0 can run once either has finished, giving 4 orders (P2 P3 P1 P0 P4, P2 P3 P1 P4 P0, P2 P3 P4 P0 P1, P2 P3 P4 P1 P0). After P2, P4 the pool is (3,2,3,1): P0 and P3 can run, and P1 only after P3, giving another 4. Total 8 safe sequences. The state is safe, but answering 1 confuses 'safe' with 'has a unique safe order'.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-109","question":"Use the same state: Allocation P0 (0,1,0,1), P1 (2,0,0,1), P2 (1,1,1,0), P3 (0,0,2,1), P4 (1,0,1,0); Max P0 (3,2,2,2), P1 (2,1,1,3), P2 (2,2,1,1), P3 (1,2,3,2), P4 (3,1,2,1); Available (1,1,1,1). Considered separately, can the banker's algorithm immediately grant (i) P4's request (1,0,0,0) and (ii) P1's request (0,0,1,0)?","options":["Neither can be granted","Only P4's request can be granted","Both can be granted","Only P1's request can be granted"],"answer":3,"explanation":"Both requests are within the requester's need and within Available, so the safety test decides. (i) Granting P4 leaves Available (0,1,1,1). Every process then needs at least one A (P0 3, P2 1, P3 1, P4 1) except P1, which needs 2 of D - nobody can finish, so the state is unsafe and P4 must wait. (ii) Granting P1 leaves (1,1,0,1). P2 needs (1,1,0,1) and can finish, releasing to (2,2,1,1); then P3 or P4 can run, and so on to a complete safe sequence. A request that fits in Available is not automatically safe.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-110","question":"A system with resource types A, B, C (several instances each) runs the deadlock-detection algorithm. Allocation: P0 (0,1,0), P1 (2,0,0), P2 (3,0,3), P3 (2,1,1), P4 (0,0,2). Current requests: P0 (0,0,0), P1 (2,0,2), P2 (0,0,1), P3 (1,0,0), P4 (0,0,2). Which processes are deadlocked if Available is (0,0,0), and which if Available is (0,0,1)?","options":["(0,0,0): P1, P2, P3 and P4; (0,0,1): none","(0,0,0): none; (0,0,1): none","(0,0,0): P1, P2, P3 and P4; (0,0,1): P1 only","(0,0,0): P1 and P2 only; (0,0,1): none"],"answer":0,"explanation":"Detection treats current requests like needs. With (0,0,0) only P0 (requesting nothing) can finish; it returns (0,1,0), which satisfies none of the others, so P1-P4 are deadlocked. With (0,0,1), P0 finishes (work (0,1,1)), then P2 (request (0,0,1)) finishes and returns (3,0,3) for (3,1,4); now P3 and P4 finish, and finally P1 (2,0,2). One spare instance of C breaks the whole deadlock, so stopping after the first pass and declaring P1 deadlocked is wrong.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-111","question":"Shared int x = 1. Thread T1 executes `x = x + 1;` twice; thread T2 executes `x = x * 2;` once. Each statement compiles to a load of x into a private register, the arithmetic, and a store back to x; only individual loads and stores are atomic. Which set contains exactly the possible final values of x?","options":["{4, 6}","{2, 3, 4, 5, 6}","{3, 4, 5, 6}","{2, 3, 4, 5, 6, 8}"],"answer":1,"explanation":"Serial orders give 6 (T2 first: 2, 3, 4), 5 (T2 between: 2, 4, 5) and 4 (T2 last: 3, 6). Lost updates add more. If T2 loads 1, T1 does both increments (x = 3) and T2 then stores 2, the result is 2. If T1's first increment loads 1, T2 runs completely (x = 2), and T1 stores 2 and increments to 3, the result is 3. Nothing can exceed 6, since that needs both increments before the doubling. So the set is {2, 3, 4, 5, 6}; 8 would need a value that was never computed.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-112","question":"Semaphores a = 0 and b = 0. Three processes run concurrently:\nP: print('A'); signal(a); wait(b); print('B');\nQ: wait(a); print('C'); signal(b); signal(a);\nR: wait(a); print('D'); signal(b);\nWhich statement is correct?","options":["ACBD, ACDB and ADCB are all possible complete outputs","The only complete outputs are ACBD and ACDB, and deadlock is impossible","The only complete outputs are ACBD and ACDB, and the system can also deadlock after printing ADB","The output is always ACBD"],"answer":2,"explanation":"After A, the single signal(a) wakes either Q or R. If Q wins, it prints C, signals b and passes a on to R; P (waiting on b) and R then race, giving ACBD or ACDB. If R wins, it prints D and signals b, so P prints B, but nobody ever signals a again: Q waits forever after the output ADB. ADCB is impossible because C requires a, which only Q itself would re-signal.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-113","question":"Two processes (i = 0, 1; j = 1 - i) share bool flag[2] = {false, false} and int turn, and each runs entry code, then its critical section, then flag[i] = false. Every individual read and write is atomic and sequentially consistent. Which entry code guarantees both mutual exclusion and freedom from deadlock?\nV1: turn = j; flag[i] = true; while (flag[j] && turn == j);\nV2: flag[i] = true; turn = i; while (flag[j] && turn == j);\nV3: flag[i] = true; turn = i; while (flag[j] && turn == i);\nV4: flag[i] = true; while (flag[j]);","options":["V1 and V4","V1 only","V2 and V3","V3 only"],"answer":3,"explanation":"V3 is Peterson's algorithm with the roles of turn mirrored: whoever writes turn last is the one that waits, so both cannot pass the loop, and the earlier writer always gets through. V1 swaps the two writes: P0 sets turn = 1, P1 sets turn = 0 and flag[1], enters (flag[0] still false), then P0 sets flag[0] and sees turn == 0 != 1, entering too. V2 waits on the wrong value: P0 sets flag[0] and turn = 0 and enters while flag[1] is false; P1 then sets flag[1] and turn = 1, sees turn != 0 and walks in as well. V4 is safe but both can set their flags and then spin forever - a deadlock. All four were checked by exhaustively exploring every interleaving.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-114","question":"How many lines print the value 3, and what is the sum of all the values printed? (Assume every fork() succeeds.)\n```c\nint main() {\n    int c = 0;\n    for (int i = 0; i < 4; i++)\n        if (fork() == 0)\n            c += i;\n    printf(\"%d\\n\", c);\n}\n```","options":["4 lines print 3; the sum is 48","2 lines print 3; the sum is 48","4 lines print 3; the sum is 24","1 line prints 3; the sum is 96"],"answer":0,"explanation":"There are 2^4 = 16 processes, and each is identified by the set of iterations in which it was the child; its c is the sum of those i values. c = 3 for the sets {3}, {0, 3}, {1, 2} and {0, 1, 2} - note that being the child at i = 0 adds nothing - so 4 lines. Each i is in exactly half of the 16 sets, so the total is 8 x (0 + 1 + 2 + 3) = 48. 24 counts each i in only 4 processes; 2 forgets the sets that include i = 0.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-115","question":"A buddy allocator manages 1024 KB and splits blocks in powers of two, always using the lowest-addressed free block of the needed size. Starting empty, it serves: A = 100 KB, B = 240 KB, C = 60 KB, D = 130 KB, free A, E = 50 KB, free C, free B. How many free blocks are there at the end, and how large is the biggest single request it can then satisfy?","options":["3 free blocks; 512 KB","4 free blocks; 256 KB","4 free blocks; 704 KB","2 free blocks; 512 KB"],"answer":1,"explanation":"A takes 128 KB at 0 (splitting 1024 into 512 + 256 + 128 + 128). B takes the 256 KB block at 256. C splits the 128 KB at 128 into two 64s and takes the one at 128. D splits 512 at 512 and takes 256 at 512, leaving 256 at 768. Freeing A gives 128 at 0, whose buddy (128 at 128) is split, so no merge. E takes the 64 at 192. Freeing C gives 64 at 128, but its buddy at 192 is E, so no merge. Freeing B gives 256 at 256, whose buddy at 0 is not whole. Free: 128 at 0, 64 at 128, 256 at 256, 256 at 768 - 704 KB in 4 blocks, but no block larger than 256 KB. Buddies merge only with their exact partner, which is why the free space is fragmented.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-116","question":"A disk has cylinders 0-499. The head is at 237 and is moving towards cylinder 0. Pending requests: 312, 45, 401, 198, 260, 12, 477, 150, 233. Among FCFS, SSTF, SCAN, LOOK and C-LOOK, which gives the smallest total head movement, and what is it?","options":["SCAN, 714 cylinders","SSTF, 713 cylinders","LOOK, 690 cylinders","C-LOOK, 907 cylinders"],"answer":2,"explanation":"LOOK: down 237 -> 12 (225 cylinders) serving 233, 198, 150, 45, 12, then up to 477 (465): 690. SCAN goes all the way to 0 first: 237 + 477 = 714. SSTF serves 233, 260, 312, 401, 477 (greedy, nearest first) and then must travel back down to 12: 4 + 27 + 52 + 89 + 76 + 465 = 713. C-LOOK: 225 down, then jump 12 -> 477 (465) and 477 -> 260 (217) = 907. FCFS is 2086. SSTF is greedy and not optimal: the first step towards 233 commits it to sweeping up first, the wrong way.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-117","question":"A disk spins at 12,000 RPM, has 250 sectors of 512 bytes per track, an average seek time of 4 ms and a track-to-track seek time of 0.5 ms. A 1 MB file (1 MB = 2^20 bytes) is read (a) when stored on 8 consecutive tracks, each read in full after the average rotational latency, and (b) when its 2048 sectors are scattered randomly, each needing an average seek and average latency. What are the two read times?","options":["(a) 92 ms, (b) about 13.35 s","(a) 40 ms, (b) about 13.35 s","(a) 67.5 ms, (b) about 8.23 s","(a) 67.5 ms, (b) about 13.35 s"],"answer":3,"explanation":"One rotation takes 60/12000 s = 5 ms, so average latency is 2.5 ms and one sector passes in 5/250 = 0.02 ms. A track holds 250 x 512 = 128 KB, so the file is 8 tracks. (a) First track: 4 + 2.5 + 5 = 11.5 ms; each of the other 7: 0.5 + 2.5 + 5 = 8 ms; total 67.5 ms. (b) Each sector: 4 + 2.5 + 0.02 = 6.52 ms, times 2048 = 13,353 ms. Placement changes the time by a factor of about 200. 40 ms counts only the 8 rotations; 8.23 s leaves out the rotational latency in (b).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-118","question":"A machine has 40-bit virtual addresses, 16 KB pages and 4-byte page-table entries. Every page table at every level must fit in a single page. How many levels of page tables are needed, and how many entries of the outermost table can ever be used?","options":["3 levels; 4 entries","2 levels; 4096 entries","3 levels; 4096 entries","4 levels; 64 entries"],"answer":0,"explanation":"The offset takes log2(16 K) = 14 bits, leaving 26 bits of page number. One page holds 16 KB / 4 B = 4096 entries, so each level resolves 12 bits. 26 bits need ceil(26/12) = 3 levels: 12 + 12 for the inner levels and only 2 bits for the outermost, so just 2^2 = 4 of its 4096 entries are usable. Two levels would resolve only 24 bits; a single table would need 2^26 entries, i.e. 256 MB.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-119","question":"A 32-bit system uses two-level paging: 10 bits for the outer index, 10 bits for the inner index and a 12-bit offset, with 4-byte entries (so every table is one 4 KB page). A process uses only an 8 MB region starting at virtual address 6 MB (0x00600000) and a 6 MB stack at the very top of the address space. Page tables are created only where needed. How much memory do its page tables occupy?","options":["20 KB","24 KB","4 MB","32 KB"],"answer":1,"explanation":"Each inner table maps 1024 x 4 KB = 4 MB. The 8 MB region covers 6 MB to 14 MB, which touches the 4 MB slices 1 (4-8 MB), 2 (8-12) and 3 (12-16): 3 inner tables, not 2, because it does not start on a 4 MB boundary. The stack covers 4090-4096 MB, touching slices 1022 and 1023: 2 inner tables. With the outer table that is 1 + 3 + 2 = 6 pages = 24 KB. 20 KB assumes 8 MB needs only 2 inner tables; 4 MB is the size of a flat single-level table.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-120","question":"A 32-bit system uses two-level paging with a 10-bit outer index, a 10-bit inner index and a 12-bit offset. The virtual address 0xC0A8F3E7 belongs to a page mapped to frame number 0x2B1C. Which outer index, inner index and physical address does the translation use?","options":["Outer 770, inner 655, physical 0x2B1CF3E7","Outer 192, inner 168, physical 0x2B1C3E7","Outer 770, inner 655, physical 0x2B1C3E7","Outer 770, inner 143, physical 0x2B1C3E7"],"answer":2,"explanation":"0xC0A8F3E7 in binary is 1100 0000 10 | 10 1000 1111 | 0011 1110 0111. The top 10 bits are 1100000010 = 770; the next 10 are 1010001111 = 655; the last 12 give the offset 0x3E7. The physical address is the frame number followed by the 12-bit offset: 0x2B1C x 0x1000 + 0x3E7 = 0x2B1C3E7. Splitting at byte boundaries (0xC0 = 192, 0xA8 = 168) is the trap, since 10-bit fields do not align with hex digits; 0x2B1CF3E7 keeps 16 offset bits instead of 12; 143 drops the two high bits of the inner index that sit inside the hex digit A.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-121","question":"A system with a TLB and a two-level page table has TLB access time 10 ns (searched before memory), memory access time 100 ns and a TLB hit ratio of 90%; a TLB miss requires walking both levels in memory. In addition, 1 in every 100,000 memory references causes a page fault; servicing a fault takes 8 ms if the victim page is clean and 20 ms if it is dirty, and 30% of victims are dirty. Counting a faulting reference as just its service time, what is the effective access time?","options":["130 ns","About 210 ns","About 236 ns","About 246 ns"],"answer":3,"explanation":"Without faults: hit 10 + 100 = 110 ns; miss 10 + 2 x 100 (two table levels) + 100 = 310 ns; average 0.9 x 110 + 0.1 x 310 = 130 ns. Average fault service = 0.7 x 8 + 0.3 x 20 = 11.6 ms = 11,600,000 ns. EAT = (1 - 10^-5) x 130 + 10^-5 x 11,600,000 = about 130 + 116 = 246 ns. 210 ns ignores the dirty pages (8 ms only); 236 ns treats the page table as single-level; 130 ns ignores faults altogether - yet one fault in 100,000 almost doubles the access time.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-122","question":"Memory access takes 200 ns. A page fault takes 8 ms to service if the replaced page is clean and 20 ms if it is dirty, and 40% of replaced pages are dirty. What is the largest page-fault rate for which the effective access time stays within 10% of the memory access time?","options":["About 1 fault per 640,000 accesses","About 1 fault per 400,000 accesses","About 1 fault per 1,000,000 accesses","About 1 fault per 64,000 accesses"],"answer":0,"explanation":"Average service time = 0.6 x 8 + 0.4 x 20 = 12.8 ms = 12,800,000 ns. Require (1 - p) x 200 + p x 12,800,000 ≤ 220, i.e. p x 12,799,800 ≤ 20, so p ≤ 1.5625 x 10^-6, about 1 fault in 640,000 accesses. Using only the 8 ms clean time gives 1 in 400,000, using 20 ms for every fault gives 1 in 1,000,000, and 1 in 64,000 is an order-of-magnitude slip. The tolerance is tiny because a fault is about 64,000 times slower than a memory access.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-123","question":"An inode has 10 direct pointers, one single-indirect, one double-indirect and one triple-indirect pointer. Blocks are 2 KB and block pointers are 8 bytes. What is the largest possible file size, to the nearest hundredth of a GiB?","options":["About 256.50 GiB","About 32.13 GiB","About 64.25 GiB","About 0.13 GiB"],"answer":1,"explanation":"One block holds 2048/8 = 256 pointers. Data blocks reachable: 10 + 256 + 256^2 + 256^3 = 10 + 256 + 65,536 + 16,777,216 = 16,843,018. Times 2 KB = 34,494,500,864 bytes, about 32.13 GiB, almost all of it through the triple-indirect pointer. 256.50 GiB assumes 4-byte pointers (512 per block); 0.13 GiB stops at the double-indirect level; 64.25 GiB multiplies 256 pointers per block by a 4 KB data block, mixing two block sizes.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-124","question":"A Unix-style inode has 12 direct pointers plus single-, double- and triple-indirect pointers; blocks are 4 KB and pointers 4 bytes. With the inode already in memory and no other blocks cached, a process reads the byte at offset 50,000,000 of a large file. Through which pointer is it reached, and how many disk blocks must be read?","options":["The double-indirect pointer (entry 11, then entry 943); 3 block reads","The single-indirect pointer; 2 block reads","The double-indirect pointer (entry 10, then entry 931); 3 block reads","The triple-indirect pointer; 4 block reads"],"answer":2,"explanation":"Logical block = floor(50,000,000 / 4096) = 12,207. A block holds 1024 pointers, so blocks 0-11 are direct and 12-1035 are single-indirect. 12,207 is beyond 1035, so it is reached through the double-indirect pointer, at relative block 12,207 - 1036 = 11,171 = 10 x 1024 + 931. Reads: the double-indirect block, the single-indirect block found at its entry 10, then the data block at entry 931 of that one - 3 reads. Dividing by 4000 instead of 4096 or forgetting to subtract the 1036 earlier blocks gives the wrong entries.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-125","question":"Each process in a system spends 70% of its time waiting for I/O, independently of the others. Using the model CPU utilisation = 1 - p^n, what is the smallest degree of multiprogramming n that achieves at least 75% CPU utilisation, and what utilisation does it give?","options":["n = 5, about 83%","n = 3, about 66%","n = 2, about 51%","n = 4, about 76%"],"answer":3,"explanation":"With p = 0.7: n = 1 gives 30%, n = 2 gives 1 - 0.49 = 51%, n = 3 gives 1 - 0.343 = 65.7%, n = 4 gives 1 - 0.2401 = 76%. So 4 processes are the minimum. The model assumes there is enough memory for all of them; once added processes no longer fit, page faults raise the effective I/O wait and utilisation falls - the onset of thrashing. Working the formula as p x n or using 0.3 as the wait probability gives the other answers.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-126","question":"Round Robin is used with a quantum of 4 ms and a context-switch time of 1 ms. There are always 10 CPU-bound processes ready and none does I/O. What fraction of CPU time does useful work, and how long does a process wait between the end of one of its quanta and the start of its next?","options":["80%; 46 ms","80%; 36 ms","75%; 46 ms","80%; 45 ms"],"answer":0,"explanation":"Every 4 ms quantum is followed by a 1 ms switch, so useful work is 4/(4 + 1) = 80%. After a process's quantum ends, each of the other 9 processes needs a switch in plus its 4 ms quantum, and then one more switch brings the CPU back: 10 x 1 + 9 x 4 = 46 ms. 36 ms ignores the switches, 45 ms forgets the final switch back, and 75% divides the switch time by the quantum alone. Raising efficiency to 90% would need a 9 ms quantum and a gap of 91 ms - the usual trade-off between overhead and response time.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-operating-systems-127","question":"A TLB has 64 entries. With 4 KB pages, what is its reach (the memory it can map without a miss)? If 16 of the entries instead map 2 MB huge pages and the other 48 map 4 KB pages, what is the reach?","options":["256 KB; 32,768 KB","256 KB; 32,960 KB","64 KB; 32,960 KB","256 KB; 131,072 KB"],"answer":1,"explanation":"Reach = entries x page size. 64 x 4 KB = 256 KB. Mixed: 48 x 4 KB + 16 x 2048 KB = 192 + 32,768 = 32,960 KB, about 32 MB, over a hundred times more - which is why large working sets such as databases use huge pages. 32,768 KB forgets the 48 small-page entries, and 131,072 KB treats all 64 entries as 2 MB pages.","difficulty":"very-hard","source":"Product company interview · GATE level"},
];

export default questions;
